import { db } from "@/lib/db";
import { formatINR } from "@/lib/money";
import { cn, formatDate } from "@/lib/utils";
import { PageHeader, Panel, Table, td } from "@/components/admin/ui";
import { CouponForm, CouponToggle } from "@/components/admin/SmallForms";

export default async function AdminCoupons() {
  const coupons = await db.coupon.findMany({ orderBy: { createdAt: "desc" }, include: { _count: { select: { orders: true } } } });
  return (
    <>
      <PageHeader title="Coupons" description="Discount codes customers can apply at checkout." />
      <Panel title="Create coupon" className="mb-6"><CouponForm /></Panel>
      <div className="rounded-lg border border-line bg-white">
        <Table head={["Code", "Discount", "Min order", "Used", "Valid until", "Status", ""]}>
          {coupons.map((c) => (
            <tr key={c.id} className={cn(!c.isActive && "opacity-50")}>
              <td className={td}><span className="font-mono font-semibold">{c.code}</span>{c.description && <span className="block text-xs text-muted">{c.description}</span>}</td>
              <td className={td}>{c.type === "PERCENT" ? `${c.value}%` : formatINR(c.value)}{c.maxDiscount ? <span className="text-xs text-muted"> (max {formatINR(c.maxDiscount)})</span> : null}</td>
              <td className={td}>{formatINR(c.minOrderAmount)}</td>
              <td className={cn(td, "tabular-nums")}>{c.usedCount}{c.usageLimit ? ` / ${c.usageLimit}` : ""}</td>
              <td className={td}>{c.validTo ? formatDate(c.validTo) : "No expiry"}</td>
              <td className={td}>{c.isActive ? "Active" : "Disabled"}</td>
              <td className={td}><CouponToggle id={c.id} isActive={c.isActive} /></td>
            </tr>
          ))}
        </Table>
      </div>
    </>
  );
}
